package goav1_test

import "testing"

// Same public decode, reset and warmup lifecycle on each side of the screen.
func BenchmarkFilmGrainDirectPublication(b *testing.B) {
	b.Run("8bit_444_96x96_3frames", func(b *testing.B) {
		benchmarkDecodeHighLevelProfileClip(b, "internal/av1/testvector/testdata/profiles/profile1-444-8bit-filmgrain-96x96.ivf", 3)
	})
	b.Run("10bit_444_96x96_3frames", func(b *testing.B) {
		benchmarkDecodeHighLevelProfileClip(b, filmGrainProfileBenchVectorPath, 3)
	})
}

