import datetime, hashlib, json, math, os, re, subprocess
from pathlib import Path
A=Path('/private/tmp/decoder-grain-direct-20261018')
root=Path('/Users/thesyncim/.codex/worktrees/decoder-intra-endpoints/goav1')
files={'baseline':A/'baseline-main.test','candidate':A/'candidate-v1.test'}
expected={'baseline':'29553aba47f8aeb22a6fa6df1ecd877dcfc6009ab92b125d9db922c4682f9377','candidate':'84ee8579f069030213c77193492136302b11729027c6cad7640cf8374157dd56'}
cases=['8bit_444_96x96_3frames','10bit_444_96x96_3frames']
commands=[]
for pair,order in enumerate([['baseline','candidate'],['candidate','baseline'],['baseline','candidate']],1):
    for case in cases:
        for side in order:
            cmd=[str(files[side]),'-test.run=^$','-test.bench=^BenchmarkFilmGrainDirectPublication$/^'+case+'$','-test.benchtime=200x','-test.count=1','-test.cpu=1','-test.benchmem']
            commands.append({'pair':pair,'case':case,'side':side,'command':cmd})
manifest={'baseline_revision':'6605b664622f9ea290a6543662f51b19b923d873','hashes':expected,'commands':commands,'expected_rows':12,'statistic':'1-exp(mean(log(candidate_ns/base_ns))), paired per case','env':{'GOMAXPROCS':'1','GOGC':'100'},'scope':'8bit affected,10bit control; grain absent measured18clip gap corpus'}
manifest['promotion_guard']={'affected_8bit_min_paired_geomean_saving':0.005,'affected_8bit_min_faster_pairs':2,'control_10bit_max_paired_geomean_regression':0.01,'steady_allocs_per_op':0,'all_parity_gates_required':True,'scope':'Grain is absent from measured18clip dav1d-gap corpus; cannot close that measured corpus gap.'}
(A/'screen-v1-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
if os.environ.get('RUN_EXCLUSIVE_SCREEN')!='1':
    print('Manifest prepared; exclusive grant required to run.')
    raise SystemExit(0)
for side,f in files.items():
    assert hashlib.sha256(f.read_bytes()).hexdigest()==expected[side],side
out=A/'screen-v1';out.mkdir(exist_ok=False)
records=[]
env=os.environ.copy();env.update(manifest['env'])
for i,row in enumerate(commands):
    log=out/f'{i+1:02d}-pair{row["pair"]}-{row["case"]}-{row["side"]}.txt'
    start=datetime.datetime.now(datetime.timezone.utc).isoformat()
    p=subprocess.run(row['command'],cwd=root,env=env,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
    log.write_text(p.stdout)
    matches=re.findall(r'^BenchmarkFilmGrainDirectPublication/(\S+)\s+(\d+)\s+([0-9.]+) ns/op\s+.*?([0-9]+) B/op\s+([0-9]+) allocs/op',p.stdout,re.M)
    record={**row,'log':str(log),'start':start,'returncode':p.returncode,'matches':matches}
    records.append(record)
    (out/'raw-rows.json').write_text(json.dumps(records,indent=2)+'\n')
    assert p.returncode==0 and len(matches)==1,(row,p.stdout)
    name,n,ns,b,alloc=matches[0]
    assert name in (row['case'],row['case']+'-1') and int(n)==200,(name,n)
    record.update(ns_per_op=float(ns),bytes_per_op=int(b),allocs_per_op=int(alloc),actual_case=name)
    print(f'{i+1}/12 {row["case"]} pair{row["pair"]} {row["side"]}: {ns} ns/op {alloc} allocs/op',flush=True)
summary={}
for case in cases:
    pairs=[]
    for pair in (1,2,3):
        r={x['side']:x for x in records if x['case']==case and x['pair']==pair}
        ratio=r['candidate']['ns_per_op']/r['baseline']['ns_per_op']
        pairs.append({'pair':pair,'baseline_ns':r['baseline']['ns_per_op'],'candidate_ns':r['candidate']['ns_per_op'],'candidate_over_baseline':ratio,'saving_fraction':1-ratio})
    summary[case]={'pairs':pairs,'paired_geomean_saving_fraction':1-math.exp(sum(math.log(p['candidate_over_baseline']) for p in pairs)/3)}
(out/'raw-rows.json').write_text(json.dumps(records,indent=2)+'\n')
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps(summary,indent=2))
